-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "esMX" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.rogue.dps.Name"] = "DPS cuerpo a cuerpo"
L["rm.era.rogue.dps.Description"] = "Niveles 1–60, todas las especializaciones, también en reinos Hardcore y Autosuficiente; basada en simulador, Icy Veins y Wowhead. Desde Sigilo: Premeditación, Emboscada con una daga cuando el objetivo no te mira, Golpe bajo en solitario, Garrote fuera de bandas. En combate: Contestación, Hacer picadillo desde un punto de combo cuando falta contra un élite o un objetivo con mucha salud (renovado con cinco puntos en sus tres últimos segundos), Exponer armadura con cinco puntos en grupo cuando tienes Exponer armadura mejorado 2/2 y nadie usa Hender armadura, un Eviscerar de dos puntos sobre un objetivo a punto de morir y, si no, Eviscerar con cinco y ningún generador por encima de cinco. El generador depende de lo que conozcas: Golpe fantasmal y Hemorragia fuera de bandas, Puñalada con una daga cuando el objetivo no te mira y, si no, Golpe siniestro. Recordatorios: venenos en cada arma (Veneno mortal en un arma de la mano izquierda si la llevas), Patada, Té de cardo, Aluvión de acero y Subidón de adrenalina contra élites o dos enemigos con Hacer picadillo activo, Sangre fría con cinco puntos, Evasión en solitario cuando estás herido. Esfumarse, Gubia, Preparación, Golpe en los riñones y las habilidades raciales aparecen en la lista pero desactivados; Amago, Sprint, Ceguera, Porrazo y el posicionamiento quedan a tu cargo."
L["rm.era.rogue.dps.simulator.Name"] = "Espadas, Golpe siniestro sincronizado con los golpes (simulador)"
L["rm.era.rogue.dps.simulator.Description"] = "El orden de Combate más exigente («sweaty») de simulador para Especialización en espadas, una alternativa a la rotación integrada de DPS cuerpo a cuerpo recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Golpe siniestro solo justo después de un golpe con la mano derecha (2,0 segundos o más hasta el siguiente, ajustado para una espada de velocidad 2,6–2,8; cámbialo en un duplicado), salvo que la energía esté casi llena o el objetivo esté a punto de morir, para que el ataque de espada adicional no retrase tu golpe. Eviscerar con cinco también espera a Hacer picadillo, a tener la energía llena o a un objetivo a punto de morir. Por lo demás, como la rotación integrada recomendada."
L["rm.era.rogue.dps.warcrafttavern.Name"] = "DPS cuerpo a cuerpo, remates de cinco puntos (Warcraft Tavern)"
L["rm.era.rogue.dps.warcrafttavern.Description"] = "El método de Warcraft Tavern, una alternativa a la rotación integrada de DPS cuerpo a cuerpo recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Todo remate espera a cinco puntos de combo para que Golpes despiadados lo reembolse. Hacer picadillo se usa desde su segundo rango (nivel 42) cuando falta o está a punto de terminar; si no, Eviscerar; sin Hacer picadillo con pocos puntos, sin Eviscerar sobre objetivos a punto de morir y sin Exponer armadura (lo cubre el Hender armadura de un guerrero). Las mismas aperturas, generadores y recordatorios que la rotación integrada recomendada."
L["rm.forever.rogue.dps.Name"] = "DPS cuerpo a cuerpo"
L["rm.forever.rogue.dps.Description"] = "Daño cuerpo a cuerpo para todas las especializaciones de pícaro del nivel 1 al 60, basada en Icy Veins, Wowhead y Warcraft Tavern. El generador depende de lo que conozcas: Mutilar (Golpe siniestro para el quinto punto), Hemorragia, Puñalada cuando el objetivo no te mira y, si no, Golpe siniestro. Desde Sigilo abre con Premeditación, Golpe bajo en solitario, Garrote para Sutileza contra élites en grupo y, si no, Emboscada o Garrote. Mantiene Hacer picadillo y Veneno, usa Exponer armadura en grupo contra élites cuando ningún guerrero tiene cinco Hender armadura, y después gasta cinco puntos en Ruptura (Sutileza, combates largos) o Eviscerar, y nunca acumula más de cinco. Recordatorios: venenos en cada arma, Patada, Aluvión de acero y Subidón de adrenalina contra grupos de enemigos y élites, Sangre fría, Evasión, Amago, Té de cardo y Preparación. Quedan a tu cargo: Esfumarse, Sprint, Golpe en los riñones, Ceguera, Porrazo y el posicionamiento. Forever restringe los datos de combate, así que Rotation Master muestra esta rotación integrada como referencia y todavía no la selecciona automáticamente."
L["rm.forever.rogue.subtlety.warcrafttavern.Name"] = "Sutileza, build de Emboscada (Warcraft Tavern)"
L["rm.forever.rogue.subtlety.warcrafttavern.Description"] = "La build de Sutileza con Emboscada/Degollador de Warcraft Tavern: Premeditación y Emboscada en cada apertura, de nuevo Emboscada siempre que Degollador lo permita, Puñalada por la espalda como generador (Hemorragia cuando el objetivo te mira), Golpe fantasmal cada vez que esté disponible, y Hacer picadillo y después Eviscerar con cinco puntos, sin Ruptura. Te recuerda usar Esfumarse para otra Emboscada contra un jefe tanqueado. Elígela en lugar de la rotación integrada de pícaro recomendada si tomaste los talentos de Degollador; se aplica con Sutileza como tu árbol de talentos principal y Degollador en tus talentos. Los mismos recordatorios de venenos y tiempos de reutilización que la rotación integrada recomendada. Una alternativa a la rotación integrada de DPS de pícaro recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad."
L["rm.forever.rogue.subtlety.wowhead.Name"] = "Sutileza, build de Garrote (Wowhead)"
L["rm.forever.rogue.subtlety.wowhead.Description"] = "La Sutileza de Wowhead: Premeditación y Garrote en cada apertura, y Esfumarse (y después Preparación) usado dentro de la rotación para volver a abrir con Garrote cuando el anterior haya expirado. Hacer picadillo siempre activo, Exponer armadura en grupo, Ruptura como remate de cinco puntos y Hemorragia como único generador. Esto gasta Esfumarse, tu vía de escape, en daño: elígela a propósito. Se aplica con Sutileza como tu árbol de talentos principal, Tretas sucias en tus talentos y Premeditación conocida. Los mismos recordatorios de venenos y tiempos de reutilización que la rotación integrada recomendada. Una alternativa a la rotación integrada de DPS de pícaro recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad."
L["rm.mop.rogue.assassination.Name"] = "Recomendada"
L["rm.mop.rogue.assassination.Description"] = "Recomendada para Asesinato, del nivel 10 al 90 (simulador y Wowhead para la fase 5, con los pasos de subida de nivel de Icy Veins). Abre desde Sigilo con Golpe bajo en solitario y, si no, con Mutilar (Despachar con Punto ciego, con una daga). Mantiene Hacer picadillo (Envenenar lo renueva desde el nivel 60) y Ruptura en el objetivo, gasta cinco puntos en Envenenar mientras dure Ruptura y cuatro puntos para mantener el beneficio de Envenenar cuando no tienes Anticipación, y después Marcado para morir, Despachar por debajo del 35 % o con Punto ciego (requiere una daga en la mano principal), y Mutilar. Contra cuatro o más enemigos luchando contra ti: Hacer picadillo, Tempestad carmesí con siete enemigos, Ruptura, Envenenar y Abanico de cuchillos; aplicar Ruptura a otros objetivos con Tab queda a tu cargo. En solitario añade Reponerse y un Golpe en los riñones cuando tienes poca salud. Recordatorios: venenos, Patada, Vendetta en combates largos, Hojas de las Sombras con Vendetta, Esfumarse y Preparación durante Vendetta, Paso de las Sombras a distancia, Evasión en solitario. Quedan a tu cargo: Secretos del oficio y Exponer armadura (en la lista pero desactivados), Amago, Sprint y el posicionamiento."
L["rm.mop.rogue.assassination.icyveins.Name"] = "Envenenar con cinco (Icy Veins)"
L["rm.mop.rogue.assassination.icyveins.Description"] = "Desactivada por defecto. El orden de Icy Veins y Method: Esfumarse cada vez que esté disponible para un Mutilar desde sigilo, Vendetta cada vez que esté disponible cuando el combate sea lo bastante largo, Envenenar solo con cinco puntos, Ruptura siempre activa, Despachar por debajo del 35 % o con Punto ciego, Mutilar. De cuatro a ocho enemigos: Abanico de cuchillos con Ruptura con tres puntos o más; con nueve o más: solo Abanico de cuchillos y Envenenar. La rotación integrada de Asesinato recomendada sigue en su lugar los consejos más recientes de la fase 5; para usar esta, actívala y desactiva la recomendada."
L["rm.mop.rogue.combat.Name"] = "Recomendada"
L["rm.mop.rogue.combat.Description"] = "Recomendada para Combate, del nivel 10 al 90 (Wowhead y simulador para la fase 5). Desde el parche de Asedio de Orgrimmar, Golpe siniestro cuesta 50 de energía, así que Golpe revelador es el generador y Golpe siniestro solo se usa bajo Ansia de sangre o Heroísmo con Subidón de adrenalina (y antes del nivel 20). Abre con Golpe bajo en solitario y, si no, con Emboscada. Mantiene Hacer picadillo desde dos puntos y Golpe revelador en el objetivo, gasta cinco puntos solo mientras Golpe revelador esté activo (Hacer picadillo, Ruptura en un combate largo contra un solo objetivo sin Aluvión de acero, Eviscerar) y espera a tener energía con cinco. Contra ocho o más enemigos: Hacer picadillo, Tempestad carmesí y Abanico de cuchillos. En solitario añade Reponerse y Golpe en los riñones. Recordatorios: venenos, Patada, activar Aluvión de acero contra dos o más enemigos y desactivarlo después, Subidón de adrenalina con poca energía junto con Hojas de las Sombras, Asesinato múltiple, Esfumarse y Preparación para Emboscada durante Perspicacia profunda, Paso de las Sombras, Evasión en solitario. Quedan a tu cargo: Secretos del oficio y Exponer armadura (en la lista pero desactivados), Amago y colocarte detrás del objetivo para Emboscada."
L["rm.mop.rogue.combat.hekili.Name"] = "Anticipación (Hekili)"
L["rm.mop.rogue.combat.hekili.Description"] = "Desactivada por defecto. El orden de Hekili para Combate en MoP con Anticipación: Golpe revelador es el único generador, incluso bajo Ansia de sangre; los remates esperan a Perspicacia profunda, a cuatro cargas de Anticipación o a que vuelva Hojas de las Sombras, y después Hacer picadillo, Ruptura sobre uno o dos objetivos que vayan a vivir mucho, Tempestad carmesí con siete enemigos y Eviscerar; Hacer picadillo se renueva antes de tiempo con 11 acumulaciones de Astucia del bandido; Abanico de cuchillos desde cuatro enemigos. Solo se aplica con el talento Anticipación. Para usarla, actívala y desactiva la rotación integrada de Combate recomendada."
L["rm.mop.rogue.combat.icyveins.Name"] = "Golpe siniestro como generador (Icy Veins)"
L["rm.mop.rogue.combat.icyveins.Description"] = "Desactivada por defecto y superada en la fase 5. El orden de Icy Veins, Warcraft Tavern, Method y wowtbc.gg de antes del parche de Asedio de Orgrimmar: Hacer picadillo, Golpe revelador siempre activo, Ruptura de cinco puntos en un combate largo contra un solo objetivo y Eviscerar, con Golpe siniestro como generador. Los mismos recordatorios y juego contra grupos de enemigos que la rotación integrada de Combate recomendada. Elígela solo si sigues esas guías; actívala y desactiva la recomendada."
L["rm.mop.rogue.subtlety.Name"] = "Recomendada"
L["rm.mop.rogue.subtlety.Description"] = "Recomendada para Sutileza con Enfoque de las Sombras, del nivel 10 al 90 (simulador y Wowhead para la fase 5). En Sigilo o en Danza de las Sombras: Premeditación, Hacer picadillo antes de iniciar el combate, remates con cinco puntos, Emboscada, Garrote. Fuera de ellos: Hacer picadillo; con cinco puntos, Hacer picadillo y Ruptura cuando estén a punto de desaparecer, y Eviscerar mientras duren ambos; Marcado para morir; Hemorragia para mantener su sangrado; Puñalada (con una daga) cuando el objetivo no te está atacando y, si no, Hemorragia. Contra tres o más enemigos: Hacer picadillo, Tempestad carmesí, Eviscerar y Abanico de cuchillos. En solitario añade Reponerse y Golpe en los riñones. Recordatorios: venenos, Patada, Danza de las Sombras con 75 de energía con Hacer picadillo y Ruptura activos, Esfumarse cuando Descubrir debilidad está terminando, Preparación, Hojas de las Sombras fuera de Danza y de Sigilo, Paso de las Sombras, Evasión en solitario. Quedan a tu cargo: colocarte detrás del objetivo (RM no puede ver la orientación), Secretos del oficio y Exponer armadura (en la lista pero desactivados)."
L["rm.mop.rogue.subtlety.warcrafttavern.Name"] = "Subterfugio (Warcraft Tavern)"
L["rm.mop.rogue.subtlety.warcrafttavern.Description"] = "Se elige automáticamente en lugar de la rotación integrada de Enfoque de las Sombras cuando tu talento de la primera fila es Subterfugio (la build de Warcraft Tavern). Premeditación y Hacer picadillo antes de iniciar el combate; en Sigilo, en Danza de las Sombras o mientras perdura Subterfugio, remates con cinco puntos y después Emboscada tantas veces como se pueda. Contra dos o tres enemigos: mantén Ruptura y gasta cinco puntos en Tempestad carmesí en lugar de Eviscerar; con cuatro o más se añade Abanico de cuchillos. Contra un objetivo: Hacer picadillo, Ruptura, Eviscerar, Hemorragia por su sangrado, Puñalada por la espalda con una daga y, si no, Hemorragia. Danza de las Sombras y Esfumarse son recordatorios con 60 de energía y Hacer picadillo activo; sincronizarlos con las activaciones de abalorios, como sugiere Tavern, queda a tu cargo."
L["rm.mop.rogue.unspecialized.Name"] = "Sin especialización"
L["rm.mop.rogue.unspecialized.Description"] = "Para los niveles 1 a 9, o para un pícaro que aún no haya elegido especialización; la rotación integrada de cada especialización toma el relevo en cuanto eliges una. Abre desde Sigilo con Golpe bajo en solitario, Emboscada o Golpe siniestro; sugiere Sigilo fuera de combate; Hacer picadillo desde dos puntos, Reponerse y Golpe en los riñones cuando estás en solitario y herido, Eviscerar con cuatro puntos (dos cuando el objetivo está a punto de morir), Golpe siniestro. Recordatorios: venenos una vez aprendidos, Patada, Evasión en solitario."
L["rm.retail.rogue.assassination.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.rogue.assassination.Description"] = "Recomendada para Asesinato en Midnight. En combate, el juego ahora oculta a los addons tus sangrados, tus beneficios, la energía, los tiempos de reutilización y la salud, así que esta rotación muestra la propia sugerencia del Asistente de combate de Blizzard (la rotación de un solo botón, que se encarga de la apertura desde sigilo, Garrote, Ruptura, Envenenar, Marca mortal y Perdición de reyes), y se detiene mientras lanzas o no tienes un enemigo como objetivo. Recordatorios de lo que deja fuera: un veneno letal y uno no letal y Sigilo entre combates, Esfumarse cuando estás fuera de sigilo en combate, Patada ante un lanzamiento interrumpible (solo se ilumina donde el juego permite leer el lanzamiento). La salud está oculta en Retail, así que Vial carmesí queda a tu criterio."
L["rm.retail.rogue.assassination.icyveins.Name"] = "De referencia (Icy Veins)"
L["rm.retail.rogue.assassination.icyveins.Description"] = "Solo de referencia, desactivada por defecto: el orden de Icy Veins y SimulationCraft mantiene los sangrados según sus temporizadores, que Midnight oculta en combate; la energía está oculta en Retail, así que se omite la acumulación de energía. Desde sigilo, Garrote y luego Emboscada. Garrote en su último 30 % mientras no tengas todos los puntos de combo, Ruptura con 5 o más en su último 30 %; con 5 o más puntos de combo, Golpe de gracia o Envenenar; con menos, Tempestad carmesí contra tres o más enemigos, Abanico de cuchillos contra dos o más cercanos, Emboscada, Mutilar. Recordatorios: Marca mortal con ambos sangrados activos, Perdición de reyes junto a ella, Esfumarse con Marca mortal lista, Puyazo sobre un objetivo con Marca de mortacechador, Té de cardo siempre que esté disponible en combate, además de los recordatorios compartidos de venenos, Sigilo y Patada."
L["rm.retail.rogue.initial.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.rogue.initial.Description"] = "Recomendada antes de elegir una especialización (mientras el juego informa de la especialización inicial del pícaro). Resalta el próximo hechizo que sugiere el Asistente de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight; espera mientras lanzas o canalizas. Junto a él, los recordatorios que comparten todas las rotaciones integradas de pícaro, cada uno una vez que conoces su hechizo. Cuando elijas una especialización al nivel 10, tomarán el relevo las rotaciones integradas de esa especialización."
L["rm.retail.rogue.outlaw.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.rogue.outlaw.Description"] = "Recomendada para Forajido en Midnight. Muestra la sugerencia del Asistente de combate de Blizzard (se encarga de la apertura desde sigilo, Lanzar huesos, Aluvión de acero, Subidón de adrenalina, Entre los ojos y los remates), y se detiene mientras lanzas o no tienes un enemigo como objetivo. Recordatorios de lo que deja fuera: venenos y Sigilo entre combates, Esfumarse cuando estás fuera de sigilo en combate, Patada. La salud está oculta en Retail, así que Vial carmesí queda a tu criterio. Huesos fuertes queda a tu cargo: el juego oculta cuántos beneficios de Lanzar huesos tienes."
L["rm.retail.rogue.outlaw.icyveins.Name"] = "De referencia (Icy Veins)"
L["rm.retail.rogue.outlaw.icyveins.Description"] = "Solo de referencia, desactivada por defecto: el orden de Icy Veins, SimulationCraft y Wowhead lee los beneficios de Lanzar huesos, las acumulaciones de Oportunidad y la energía, que Midnight oculta en combate. Desde sigilo, Emboscada. Con un punto de combo menos del máximo o más: Entre los ojos, Asesinato múltiple, Golpe de gracia, Despachar. Si no, Emboscada con Audacia, Disparo de pistola con seis acumulaciones de Oportunidad (tres con pocos puntos de combo), Emboscada, Golpe siniestro. Recordatorios: Lanzar huesos sin ninguna tirada activa, Subidón de adrenalina con dos puntos de combo o menos, Aluvión de acero mantenido contra dos o más enemigos, Carga de hojas, Preparación cuando Subidón de adrenalina, Entre los ojos y Carga de hojas están todos en reutilización. Huesos fuertes sigue siendo manual."
L["rm.retail.rogue.subtlety.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.rogue.subtlety.Description"] = "Recomendada para Sutileza en Midnight. Muestra la sugerencia del Asistente de combate de Blizzard (se encarga de la apertura desde sigilo, Hojas de las Sombras, Mordedura de Faucesangre, Danza de las Sombras, Técnica secreta y los remates), y se detiene mientras lanzas o no tienes un enemigo como objetivo. Recordatorios de lo que deja fuera: venenos y Sigilo entre combates, Patada ante un lanzamiento interrumpible. La salud está oculta en Retail, así que Vial carmesí queda a tu criterio."
L["rm.retail.rogue.subtlety.icyveins.Name"] = "De referencia (Icy Veins)"
L["rm.retail.rogue.subtlety.icyveins.Description"] = "Solo de referencia, desactivada por defecto: el orden de Icy Veins y SimulationCraft reserva Danza de las Sombras para Técnica secreta y lee Danza de las Sombras, La noche más oscura y la energía, que Midnight oculta en combate. En sigilo antes de iniciar el combate: Golpesombra. Con un punto de combo menos del máximo o más: Eviscerar con La noche más oscura, Técnica secreta en Danza de las Sombras, Golpe de gracia, Polvo negro contra tres o más enemigos, Eviscerar. Si no, Golpesombra, Tormenta de shurikens contra dos o más, Hoja de penumbra o Puñalada. Recordatorios: Mordedura de Faucesangre en Danza de las Sombras, Hojas de las Sombras con Danza de las Sombras lista, Danza de las Sombras con dos puntos de combo o menos (o seis o más) cuando Técnica secreta está lista o con Hojas de las Sombras en curso, Esfumarse fuera de sigilo con dos puntos de combo o menos."
L["rm.sod.rogue.dps.Name"] = "DPS cuerpo a cuerpo (SoD)"
L["rm.sod.rogue.dps.Description"] = "Temporada de descubrimiento, niveles 1–60, con las runas a medida que las grabas; basada en la fase 6 de simulador, Icy Veins y la fase 8 de Zockify. Desde Sigilo: Golpesombra, Garrote en grupo, Emboscada para una build de Puñalada con una daga, Golpe bajo en solitario. Con tres o más enemigos luchando contra ti: primero Trabuco, Tempestad carmesí y Abanico de cuchillos. Después, Emboscada con una activación de Degollador (con una daga), Sablazo mantenido en tres acumulaciones, Cuchillo envenenado con cuatro acumulaciones de veneno, Hacer picadillo desde dos puntos (renovado desde cuatro, salvo que Perseguir hasta el final esté grabado), Exponer armadura cuando nadie usa Hender armadura ni mantiene Veneno sebáceo, con Carnicería grabada un sangrado (Tempestad carmesí y, si no, Ruptura; ninguno con Sablazo), Envenenar con cinco (Eviscerar hasta que lo grabes) y un generador según la runa de guantes: Mutilar, Sablazo, Puñalada (con una daga) y, si no, Golpe siniestro. Recordatorios: un encantamiento temporal en cada arma, Patada, Té de cardo, Aluvión de acero, Subidón de adrenalina, Sangre fría y Evasión, y con Maestro de la sutileza grabado, Esfumarse para renovarlo y Preparación."
L["rm.sod.rogue.dps.icyveins.Name"] = "DPS cuerpo a cuerpo, Ruptura para Carnicería (SoD, Icy Veins)"
L["rm.sod.rogue.dps.icyveins.Description"] = "El orden de Temporada de descubrimiento de Icy Veins, una alternativa a la rotación integrada de DPS cuerpo a cuerpo de Temporada de descubrimiento recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Todo remate con cinco puntos de combo; primero Hacer picadillo cuando falta o está a punto de terminar, después Ruptura mantenida cuando Carnicería está grabada y después Envenenar; Cuchillo envenenado solo con cinco acumulaciones de veneno; Trabuco o Abanico de cuchillos contra tres enemigos. Las mismas aperturas, generadores y recordatorios que la rotación integrada recomendada; mantener Veneno sebáceo queda a tu cargo."
L["rm.sod.rogue.dps.zockify.Name"] = "DPS cuerpo a cuerpo, Envenenar sin extras (SoD, Zockify)"
L["rm.sod.rogue.dps.zockify.Description"] = "La lista simplificada de Temporada de descubrimiento de Zockify, una alternativa a la rotación integrada de DPS cuerpo a cuerpo de Temporada de descubrimiento recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Sin sangrados ni Exponer armadura. Cuchillo envenenado con cuatro acumulaciones de veneno, Hacer picadillo cuando falta (desde dos puntos, cuatro con Sablazo), Envenenar con cinco y después el generador de la runa de guantes. La ráfaga de Esfumarse y Sangre fría queda a tu cargo."
L["rm.sod.rogue.tank.Name"] = "Tanque (SoD)"
L["rm.sod.rogue.tank.Description"] = "Tanque de Temporada de descubrimiento, elegida cuando tienes grabada Heridas superficiales; basada en la fase 6 de simulador, Icy Veins, Zockify y Warcraft Tavern. Contestación, Daga de guardamano cada vez que esté disponible, Danza de hojas desde un punto de combo (renovada desde tres), Hacer picadillo desde tres (renovado desde cuatro), Abanico de cuchillos, Tempestad carmesí y Trabuco contra tres o más enemigos, Trabuco mientras Danza de hojas esté activa, Eviscerar con cinco con ambos beneficios activos, Cuchillo envenenado con poca energía, y después Sablazo, Mutilar o Golpe siniestro. Recordatorios: Burla en grupo cuando tu objetivo ataca a otro, Patada, Evasión por debajo de la mitad de la salud, Aluvión de acero, Subidón de adrenalina, Té de cardo y venenos de arma (el de la mano izquierda solo con un arma en esa mano). Paso de las Sombras y mantener Veneno sebáceo quedan a tu cargo."
L["rm.tbc.rogue.dps.simulator.Name"] = "DPS cuerpo a cuerpo (simulador)"
L["rm.tbc.rogue.dps.simulator.Description"] = "Niveles 1–70, todas las especializaciones. Desde sigilo: Premeditación, y después Golpe bajo en solitario o Garrote en grupo; si no, Emboscada (con una daga en la mano principal). En combate: Contestación, Hacer picadillo desde dos puntos de combo (renovado en sus dos últimos segundos), Eviscerar sobre un objetivo a punto de morir y, con cinco puntos, Ruptura si va a durar (no mientras Aluvión de acero golpea a varios objetivos); si no, Eviscerar. Genera puntos con Mutilar o Puñalada por la espalda (daga) cuando el objetivo no te está atacando; si no, con Hemorragia o Golpe siniestro. Te recuerda los venenos que faltan, Patada, Aluvión de acero y Subidón de adrenalina, Sangre fría y Evasión. Exponer armadura, Golpe en los riñones, Amago, Esfumarse y el posicionamiento quedan a tu cargo."
L["rm.tbc.rogue.dps.wowhead.Name"] = "DPS cuerpo a cuerpo (Wowhead)"
L["rm.tbc.rogue.dps.wowhead.Description"] = "Niveles 1–70, todas las especializaciones, según Wowhead. Las mismas aperturas desde sigilo, generadores y recordatorios que la versión de simulador, pero Hacer picadillo empieza desde un punto de combo y todo remate de cinco puntos es Eviscerar: sin Ruptura. Exponer armadura, Golpe en los riñones, Amago, Esfumarse y el posicionamiento quedan a tu cargo. Una alternativa a la rotación integrada de DPS cuerpo a cuerpo de simulador recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad."
